repo.harvests.py:
"""Harvest records."""


class Harvest:
    def __init__(self, field, kilos):
        self.field = field
        self.kilos = kilos

    def __repr__(self):
        return "Harvest(%r, %r)" % (self.field, self.kilos)


ROWS = [('upper', 4), ('lower', 24), ('river', 11), ('river', 56), ('hill', 45), ('upper', 33)]


def load_harvests():
    """Yield the stored harvests one at a time."""
    for field, kilos in ROWS:
        yield Harvest(field, kilos)

