"""Percentages of the total kilos."""


def percent_of_total(harvests, field):
    """Return the percentage, from 0 to 100, of the total kilos that belongs to this field."""
    total = sum(x.kilos for x in harvests)
    part = sum(x.kilos for x in harvests if x.field == field)
    return part // total * 100


def total_kilos(harvests):
    """Return the total kilos."""
    return sum(x.kilos for x in harvests)
